## Why This Is Asked

This question assesses CGO surface design for mixed-language memory ownership, parallel processing, and robust error handling in production scenarios.

## Key Concepts

- CGO memory ownership across C and Go boundaries
- Thread-safe parallel hashing and rolling state management
- JSON marshaling in C with malloc; Go copies and frees appropriately
- Ordering guarantees in a concurrent worker pool

## Code Example

```c
// block_hasher.h
#ifndef BLOCK_HASHER_H
#define BLOCK_HASHER_H

#include <stddef.h>
#include <stdint.h>

typedef struct {
    int idx;
    size_t size;
    uint8_t hash[32];
} BlockInfo;

char* compute_block_hashes(const uint8_t* blocks[], const size_t* sizes, size_t count);
void free_json_string(char* json);

#endif
```

```c
// block_hasher.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "block_hasher.h"
#include <sha256.h> // assume SHA-256 implementation

char* compute_block_hashes(const uint8_t* blocks[], const size_t* sizes, size_t count) {
    BlockInfo* infos = malloc(count * sizeof(BlockInfo));
    if (!infos) return NULL;

    SHA256_CTX rolling_ctx;
    sha256_init(&rolling_ctx);

    for (size_t i = 0; i < count; i++) {
        infos[i].idx = (int)i;
        infos[i].size = sizes[i];
        sha256_update(&rolling_ctx, blocks[i], sizes[i]);
        sha256_final_block(blocks[i], sizes[i], infos[i].hash);
    }

    uint8_t final_hash[32];
    sha256_final(&rolling_ctx, final_hash);

    // Build JSON output
    size_t json_size = 256 + count * 128;
    char* json = malloc(json_size);
    if (!json) { free(infos); return NULL; }

    int offset = 0;
    offset += snprintf(json + offset, json_size - offset,
        "{\"blocks\":[");

    for (size_t i = 0; i < count; i++) {
        char hash_hex[65];
        for (int j = 0; j < 32; j++)
            sprintf(hash_hex + j*2, "%02x", infos[i].hash[j]);

        offset += snprintf(json + offset, json_size - offset,
            "%s{\"idx\":%d,\"size\":%zu,\"hash\":\"%s\"}",
            i > 0 ? "," : "", infos[i].idx, infos[i].size, hash_hex);
    }

    char final_hash_hex[65];
    for (int j = 0; j < 32; j++)
        sprintf(final_hash_hex + j*2, "%02x", final_hash[j]);

    size_t total = 0;
    for (size_t i = 0; i < count; i++) total += sizes[i];

    snprintf(json + offset, json_size - offset,
        "],\"rolling_hash\":\"%s\",\"total_bytes\":%zu}",
        final_hash_hex, total);

    free(infos);
    return json;
}

void free_json_string(char* json) {
    free(json);
}
```

```go
// block_hasher.go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lhasher
#include "block_hasher.h"
#include <stdlib.h>
*/
import "C"
import (
    "errors"
    "fmt"
    "sync"
    "unsafe"
)

type blockResult struct {
    idx  int
    hash []byte
    size C.size_t
}

func StreamBlockHashes(blocks [][]byte) (string, error) {
    if len(blocks) == 0 {
        return "{\"blocks\":[],\"rolling_hash\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"total_bytes\":0}", nil
    }

    cBlocks := make([]*C.uint8_t, len(blocks))
    cSizes := make([]C.size_t, len(blocks))

    for i, b := range blocks {
        cBlocks[i] = (*C.uint8_t)(unsafe.Pointer(&b[0]))
        cSizes[i] = C.size_t(len(b))
    }

    result := C.compute_block_hashes(&cBlocks[0], &cSizes[0], C.size_t(len(blocks)))
    if result == nil {
        return "", errors.New("C computation failed")
    }
    defer C.free_json_string(result)

    return C.GoString(result), nil
}
```

```go
// main.go
package main

import (
    "encoding/hex"
    "errors"
    "fmt"
    "sync"
)

const numWorkers = 4

func main() {
    blocks := [][]byte{
        []byte("hello "),
        []byte("world\n"),
        []byte("test data for streaming"),
    }

    result, err := processBlocks(blocks)
    if err != nil {
        fmt.Fprintf(os.Stderr, "Error: %v\n", err)
        os.Exit(1)
    }
    fmt.Println(result)
}

func processBlocks(blocks [][]byte) (string, error) {
    if len(blocks) == 0 {
        return StreamBlockHashes(nil)
    }

    type job struct {
        idx   int
        data  []byte
    }
    type result struct {
        idx    int
        hash   [32]byte
        size   int
        err    error
    }

    jobs := make(chan job, len(blocks))
    results := make(chan result, len(blocks))

    var wg sync.WaitGroup
    for i := 0; i < numWorkers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for j := range jobs {
                hash := sha256.Sum256(j.data)
                results <- result{
                    idx:  j.idx,
                    hash: hash,
                    size: len(j.data),
                }
            }
        }()
    }

    for i, b := range blocks {
        jobs <- job{idx: i, data: b}
    }
    close(jobs)

    go func() {
        wg.Wait()
        close(results)
    }()

    blockResults := make([]result, len(blocks))
    for r := range results {
        if r.err != nil {
            return "", r.err
        }
        blockResults[r.idx] = r
    }

    // Compute rolling hash
    var rolling [32]byte
    first := true
    for i := 0; i < len(blocks); i++ {
        br := blockResults[i]
        if first {
            rolling = br.hash
            first = false
        } else {
            combined := append(rolling[:], br.hash[:]...)
            rolling = sha256.Sum256(combined)
        }
    }

    // Build JSON
    json := "{\"blocks\":["
    total := 0
    for i, br := range blockResults {
        if i > 0 {
            json += ","
        }
        json += fmt.Sprintf("{\"idx\":%d,\"size\":%d,\"hash\":\"%s\"}",
            br.idx, br.size, hex.EncodeToString(br.hash[:]))
        total += br.size
    }
    json += fmt.Sprintf("],\"rolling_hash\":\"%s\",\"total_bytes\":%d}",
        hex.EncodeToString(rolling[:]), total)

    return json, nil
}
```

## Why This Is Asked
Tests CGOA memory ownership, error propagation, and concurrency safety with a realistic image-like API.

## Key Concepts
- CGO memory management: malloc/free and Go ownership
- Proper error translation from C to Go
- Concurrency safety when CGO calls occur from multiple goroutines

## Code Example
```c
// blur.h
unsigned char* blur_image(const unsigned char* in, size_t n, int radius, size_t* out_len);
```
```c
// blur.c
unsigned char* blur_image(const unsigned char* in, size_t n, int radius, size_t* out_len) {
  if (!in || n == 0 || radius <= 0) return NULL;
  unsigned char* out = malloc(n);
  if (!out) return NULL;
  for (size_t i = 0; i < n; ++i) out[i] = in[i];
  *out_len = n;
  return out;
}
```
```go
// blur.go
// #include "blur.h"
// #include <stdlib.h>
import "C"
import (
  "errors"
  "unsafe"
)
func BlurImage(input []byte, radius int) ([]byte, error) {
  if len(input) == 0 || radius <= 0 { return nil, errors.New("invalid input") }
  var outLen C.size_t
  res := C.blur_image((*C.uchar)(unsafe.Pointer(&input[0])), C.size_t(len(input)), C.int(radius), &outLen)
  if res == nil { return nil, errors.New("blur failed") }
  out := C.GoBytes(unsafe.Pointer(res), C.int(outLen))
  C.free(unsafe.Pointer(res))
  return out, nil
}
``` 

